'use server'

import { refresh, updateTag } from 'next/cache'
import { z } from 'zod'

import { errorState, formText, successState, type ActionState } from '@/lib/admin/validation'
import { requireAdmin } from '@/lib/auth'
import { PUBLIC_CONTENT_TAG } from '@/lib/content/queries'
import { IMAGE_TYPES, MAX_IMAGE_BYTES, MAX_VIDEO_BYTES, VIDEO_TYPES, isVideoType } from '@/lib/media'
import { mediaPublicUrl } from '@/lib/supabase/config'
import { createClient } from '@/lib/supabase/server'

const mediaRecordSchema = z
  .object({
    // Paths are generated by the uploader: YYYY/MM/<uuid>.<ext>
    path: z
      .string()
      .regex(/^\d{4}\/\d{2}\/[0-9a-f-]{36}\.(jpg|png|webp|gif|avif|mp4|webm)$/, 'Invalid storage path.'),
    fileName: z.string().trim().min(1).max(255),
    mimeType: z.enum([...IMAGE_TYPES, ...VIDEO_TYPES]),
    size: z.number().int().positive(),
    width: z.number().int().positive().max(20000).nullable(),
    height: z.number().int().positive().max(20000).nullable(),
    altText: z.string().trim().max(300, 'Keep alt text under 300 characters.'),
  })
  .superRefine((input, ctx) => {
    const video = isVideoType(input.mimeType)
    if (input.size > (video ? MAX_VIDEO_BYTES : MAX_IMAGE_BYTES)) {
      ctx.addIssue({
        code: 'custom',
        path: ['size'],
        message: video ? 'Videos must be 50 MB or smaller.' : 'Images must be 5 MB or smaller.',
      })
    }
  })

export type MediaRecordInput = z.input<typeof mediaRecordSchema>

/** The new library item's id and public URL are returned so a form can use it straight away. */
export type MediaRecordResult = ActionState & { id?: string; url?: string | null }

/** Records a file the browser has already uploaded to the `media` bucket. */
export async function createMediaRecord(input: MediaRecordInput): Promise<MediaRecordResult> {
  const admin = await requireAdmin()
  const parsed = mediaRecordSchema.safeParse(input)
  if (!parsed.success) return errorState(parsed.error.issues[0]?.message ?? 'Invalid upload.')

  const { path, fileName, mimeType, size, width, height, altText } = parsed.data
  const supabase = await createClient()
  const { data, error } = await supabase
    .from('media')
    .insert({
      storage_path: path,
      file_name: fileName,
      mime_type: mimeType,
      size_bytes: size,
      width,
      height,
      alt_text: altText,
      uploaded_by: admin.id,
    })
    .select('id')
    .single()

  if (error) {
    console.error(`[admin] media record failed: ${error.message}`)
    // Do not leave an untracked file behind.
    await supabase.storage.from('media').remove([path])
    return errorState('The file could not be saved to the library. Please try again.')
  }

  refresh()
  return { ...successState(`Uploaded ${fileName}.`), id: data.id, url: mediaPublicUrl(path) }
}

export async function updateMediaAlt(id: string, _previous: ActionState, formData: FormData): Promise<ActionState> {
  await requireAdmin()
  if (!z.guid().safeParse(id).success) return errorState('Unknown image.')

  const altText = formText(formData, 'alt_text').trim()
  if (altText.length > 300) return errorState('Keep alt text under 300 characters.')

  const supabase = await createClient()
  const { error } = await supabase.from('media').update({ alt_text: altText }).eq('id', id)
  if (error) {
    console.error(`[admin] media update failed: ${error.message}`)
    return errorState('The alt text could not be saved.')
  }

  // Alt text of cover images is rendered on public pages.
  updateTag(PUBLIC_CONTENT_TAG)
  return successState('Alt text saved.')
}

export async function deleteMedia(id: string): Promise<ActionState> {
  await requireAdmin()
  if (!z.guid().safeParse(id).success) return errorState('Unknown file.')

  const supabase = await createClient()
  const { data: media, error: loadError } = await supabase
    .from('media')
    .select('storage_path')
    .eq('id', id)
    .maybeSingle()
  if (loadError) return errorState('The file could not be deleted. Please try again.')
  if (!media) return errorState('This file no longer exists.')

  const { error } = await supabase.from('media').delete().eq('id', id)
  if (error) {
    console.error(`[admin] media delete failed: ${error.message}`)
    return errorState('The file could not be deleted. Please try again.')
  }

  // Covers are cleared by the foreign key; icons and videos are referenced by URL.
  const url = mediaPublicUrl(media.storage_path)
  if (url) {
    const cleared = await Promise.all([
      supabase.from('content_items').update({ icon_url: null }).eq('icon_url', url),
      supabase.from('content_items').update({ video_url: null }).eq('video_url', url),
    ])
    for (const { error: clearError } of cleared) {
      if (clearError) console.error(`[admin] could not clear a reference to a deleted file: ${clearError.message}`)
    }
  }

  const { error: storageError } = await supabase.storage.from('media').remove([media.storage_path])
  if (storageError) console.error(`[admin] could not remove file: ${storageError.message}`)

  updateTag(PUBLIC_CONTENT_TAG)
  return successState('File deleted.')
}
